G=load()
def f(g,minsize=None):
    h,w=len(g),len(g[0]); bg=g[0][0]; cc=set(v for r in g for v in r)-{bg}; cc=cc.pop()
    def ray(i,j,d):
        while True:
            i,j=i+d[0],j+d[1]
            if not(0<=i<h and 0<=j<w): return False
            if g[i][j]==cc: return True
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and all(ray(i,j,d) for d in ((1,0),(-1,0),(0,1),(0,-1))):
                if minsize is None or len([1 for _ in [0]]) and False: pass
                seen[i][j]=True
    # flood from seeds
    q=deque([(i,j) for i in range(h) for j in range(w) if g[i][j]==bg and seen[i][j]])
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True;q.append((ni,nj))
    out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg:
                # connected component of seeds
                seed=seen[i][j]
                if seed and (minsize is None or True): out.append(4)
    return [[4 if (g[i][j]==bg and seen[i][j]) else g[i][j] for j in range(w)] for i in range(h)]
