# Analyze wall-frame geometry: for each enclosed comp, does its surrounding wall form a simple closed loop (cycle) vs a tree/branching structure? A filled room should be wrapped by exactly one closed cycle of walls.
def wallcycle(gi,c,bg):
    # BFS over 8-connected wall cells adjacent to c; check graph has edges forming cycles covering it
    wc={(i+di,j+dj) for i,j in c for di,dj in D8 if 0<=i+di<len(gi) and 0<=j+dj<len(gi[0]) and gi[i+di][j+dj]!=bg}
    seen=set(); st=list(wc)
    while st:
        x,y=st.pop()
        if (x,y) in seen: continue
        seen.add((x,y))
        for di,dj in D8:
            n=(x+di,y+dj)
            if 0<=n[0]<len(gi) and 0<=n[1]<len(gi[0]) and gi[n[0]][n[1]]!=bg and n not in seen:
                st.append(n)
    # adjacency among wall cells
    adj={(x,y):{(x+di,y+dj) for di,dj in D8 if (x+di,y+dj) in wc} for x,y in wc}
    degs={w:len(adj[w]) for w in wc}
    return max(degs.values())
